import { useEffect, useRef } from "react";
import * as THREE from "three"; // npm i three  (>= 0.152)

// Texturas embebidas (frente y dorso del sobre). El cuerpo es exactamente #56000F;
// el material lo muestra casi sin iluminación (emissive) para que el color no se desvíe.
const FRONT =
  "data:image/png;base64,";
const BACK =
  "data:image/png;base64,";

/**
 * STIX SHARP 3D: sobre de electrolito (stick pack) que gira suavemente.
 * Fondo blanco, apto mobile. Ocupa todo el alto de la pantalla por defecto
 * (cámbialo con style/className). Se puede girar arrastrando.
 */

import { useEffect, useRef } from "react";
import * as THREE from "three";

import { useEffect, useRef } from "react";
import * as THREE from "three";

// Conservá tus imports/constantes originales de FRONT y BACK.

export default function StixSharp3DMini({
  className = "",
  maxHeight = 300,
  style = {},
  zoom = 2.2,
}) {
  const hostRef = useRef(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    const W = 1;
    const H = 4.673;
    const TMAX = 0.15;
    const SEAL = 0.05;
    const TRANS = 0.07;

    const ss = (x) => {
      x = Math.max(0, Math.min(1, x));
      return x * x * (3 - 2 * x);
    };

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.domElement.style.cssText =
      "display:block;width:100%;height:100%;touch-action:pan-y;cursor:grab";

    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(32, 1, 0.1, 100);
    const disposables = [renderer];

    const pm = new THREE.PMREMGenerator(renderer);
    const envScene = new THREE.Scene();
    envScene.background = new THREE.Color(0x707070);

    const addSoftbox = (w, h, x, y, z, intensity) => {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(w, h, 0.2),
        new THREE.MeshBasicMaterial({
          color: new THREE.Color(intensity, intensity, intensity),
        }),
      );

      mesh.position.set(x, y, z);
      mesh.lookAt(0, 0, 0);
      envScene.add(mesh);
      disposables.push(mesh.geometry, mesh.material);
    };

    addSoftbox(7, 7, 4, 5, 6, 6);
    addSoftbox(1.5, 10, -7, 0, 3, 4);
    addSoftbox(9, 3, 0, 9, 0, 4);
    addSoftbox(8, 8, 0, 2, -9, 3);
    addSoftbox(1.5, 10, 7, 0, -2, 2);

    const envRT = pm.fromScene(envScene, 0.04);
    scene.environment = envRT.texture;
    disposables.push(pm, envRT);

    scene.add(new THREE.AmbientLight(0xffffff, 0.06 * Math.PI));

    const keyLight = new THREE.DirectionalLight(
      0xffffff,
      0.18 * Math.PI,
    );
    keyLight.position.set(3, 4, 6);
    scene.add(keyLight);

    const bumpCanvas = document.createElement("canvas");
    bumpCanvas.width = 64;
    bumpCanvas.height = 1024;

    const ctx = bumpCanvas.getContext("2d");
    ctx.fillStyle = "#808080";
    ctx.fillRect(0, 0, 64, 1024);

    for (let y = 0; y < SEAL * 1024 * 0.95; y += 5) {
      [y, 1024 - 5 - y].forEach((yy) => {
        ctx.fillStyle = "#d0d0d0";
        ctx.fillRect(0, yy, 64, 2.5);

        ctx.fillStyle = "#303030";
        ctx.fillRect(0, yy + 2.5, 64, 2.5);
      });
    }

    const bump = new THREE.CanvasTexture(bumpCanvas);
    disposables.push(bump);

    const makeFace = (src, back) => {
      const geometry = new THREE.PlaneGeometry(W, H, 48, 520);
      const positions = geometry.attributes.position;
      const uv = geometry.attributes.uv;

      for (let i = 0; i < positions.count; i++) {
        const x = positions.getX(i);
        const y = positions.getY(i);
        const u = (2 * x) / W;
        const v = y / H + 0.5;
        const d = Math.min(v, 1 - v);

        const t = ss((d - SEAL) / TRANS);
        const profile = Math.pow(Math.max(0, 1 - u * u), 0.62);

        let z =
          TMAX *
          t *
          profile *
          (0.9 + 0.1 * Math.sin(Math.PI * v));

        z +=
          0.014 *
          4 *
          t *
          (1 - t) *
          Math.sin(u * 17 + 1.3) *
          profile;

        z += 0.004 * Math.sin(v * 40 + u * 5) * t * profile;
        z += 0.006;

        positions.setZ(i, back ? -z : z);
        uv.setX(i, back ? 1 - (x / W + 0.5) : x / W + 0.5);
      }

      geometry.computeVertexNormals();

      const texture = new THREE.TextureLoader().load(src);
      texture.anisotropy = 8;
      texture.colorSpace = THREE.SRGBColorSpace;

      const material = new THREE.MeshStandardMaterial({
        map: texture,
        emissiveMap: texture,
        emissive: 0xffffff,
        emissiveIntensity: 0.75,
        bumpMap: bump,
        bumpScale: 1.2,
        side: THREE.DoubleSide,
        transparent: true,
        alphaTest: 0.5,
        roughness: 0.38,
        metalness: 0.1,
        envMapIntensity: 0.2,
      });

      disposables.push(geometry, material, texture);

      return new THREE.Mesh(geometry, material);
    };

    const group = new THREE.Group();
    group.add(makeFace(FRONT, false));
    group.add(makeFace(BACK, true));
    scene.add(group);

    const resize = () => {
      const w = host.clientWidth || 1;
      const h = host.clientHeight || 1;

      renderer.setSize(w, h, false);
      camera.aspect = w / h;

      const fov = THREE.MathUtils.degToRad(camera.fov);
      const isMobile = window.matchMedia("(max-width: 767px)").matches;

      // Un factor mayor aleja la cámara y hace que el sachet se vea más chico.
      const scale = zoom * (isMobile ? 1.5 : 1);

      const fitHeight = (H / 2 / Math.tan(fov / 2)) * scale;
      const fitWidth =
        (W / 2 / Math.tan(fov / 2) / camera.aspect) * scale;

      camera.position.set(0, 0, Math.max(fitHeight, fitWidth));
      camera.lookAt(0, 0, 0);
      camera.updateProjectionMatrix();
    };

    const observer = new ResizeObserver(resize);
    observer.observe(host);
    resize();

    let rotationY = 0.4;
    let velocity = 0.6;
    let dragging = false;
    let lastX = 0;
    let lastTime = performance.now();
    let raf = 0;

    const onDown = (event) => {
      dragging = true;
      lastX = event.clientX;
      velocity = 0;
      renderer.domElement.style.cursor = "grabbing";
      renderer.domElement.setPointerCapture(event.pointerId);
    };

    const onMove = (event) => {
      if (!dragging) return;

      const dx = event.clientX - lastX;
      lastX = event.clientX;
      rotationY += dx * 0.01;
      velocity = dx * 0.01 * 60;
    };

    const onUp = () => {
      dragging = false;
      renderer.domElement.style.cursor = "grab";
    };

    const canvas = renderer.domElement;

    canvas.addEventListener("pointerdown", onDown);
    canvas.addEventListener("pointermove", onMove);
    canvas.addEventListener("pointerup", onUp);
    canvas.addEventListener("pointercancel", onUp);

    const render = (now) => {
      raf = requestAnimationFrame(render);

      const dt = Math.min((now - lastTime) / 1000, 0.05);
      lastTime = now;

      if (!dragging) {
        velocity += (0.6 - velocity) * Math.min(dt * 1.5, 1);
        rotationY += velocity * dt;
      }

      group.rotation.y = rotationY;
      group.rotation.x = Math.sin(now / 2200) * 0.05;
      group.position.y = Math.sin(now / 1800) * 0.05;

      renderer.render(scene, camera);
    };

    raf = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(raf);
      observer.disconnect();

      canvas.removeEventListener("pointerdown", onDown);
      canvas.removeEventListener("pointermove", onMove);
      canvas.removeEventListener("pointerup", onUp);
      canvas.removeEventListener("pointercancel", onUp);

      disposables.forEach((item) => item.dispose?.());

      if (canvas.parentNode === host) {
        host.removeChild(canvas);
      }
    };
  }, [zoom]);

  return (
    <div
      ref={hostRef}
      className={className}
      style={{
        position: "relative",
        width: "100%",
        height: maxHeight,
        maxHeight,
        minWidth: 0,
        minHeight: 0,
        overflow: "hidden",
        ...style,
      }}
    />
  );
}